def post_process(guards: list[OutputGuardrail], raw: str, schema: str) -> str:
    current = raw
    for g in guards:
        v = g.evaluate(current, schema)
        if v.action == "block":
            raise ValueError(f"{g.name}: {v.reason}")
        if v.action == "rewrite" and v.replacement is not None:
            current = v.replacement
    return current
